const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  const sources = (input.annotations || []).filter(a => a.type === 'url_citation').map(a => ({
    title: a.title || 'Source',
    url: a.url,
    domain: new URL(a.url).hostname
  }));

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content: input.output_text || input.output || '',
      sources,
      search_performed: true,
      raw_response: input
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      raw_response: input
    }
  }];
}

