const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  const candidate = input.candidates?.[0];
  const content = candidate?.content?.parts?.map(p => p.text).join('') || '';

  const groundingMeta = candidate?.groundingMetadata || {};
  const sources = (groundingMeta.groundingChunks || []).map(chunk => ({
    title: chunk.web?.title || 'Source',
    url: chunk.web?.uri || '',
    domain: chunk.web?.uri ? new URL(chunk.web.uri).hostname : ''
  }));

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content,
      sources,
      search_performed: sources.length > 0,
      search_queries: groundingMeta.webSearchQueries || [],
      raw_response: input
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      raw_response: input
    }
  }];
}

