const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  if (!input.normalized) {
    return [{
      json: {
        success: false,
        error: {
          code: 500,
          message: input.error || 'Failed to normalize response',
          status: 'NORMALIZE_ERROR'
        },
        meta: { provider: prevData.provider }
      }
    }];
  }

  // Parse recipes from content (simplified)
  const recipes = [];
  const content = input.content || '';

  // Try to extract recipe-like structures from the response
  const lines = content.split('\n');
  let currentRecipe = null;

  for (const line of lines) {
    if (line.match(/^\d+\.|^-|^\*/) && line.length > 20) {
      if (currentRecipe) recipes.push(currentRecipe);
      currentRecipe = {
        title: line.replace(/^[\d.\-*]+\s*/, '').substring(0, 100),
        summary: '',
        source: input.sources[recipes.length] || null
      };
    } else if (currentRecipe && line.trim()) {
      currentRecipe.summary += line + ' ';
    }
  }
  if (currentRecipe) recipes.push(currentRecipe);

  return [{
    json: {
      success: true,
      data: {
        query: prevData.query,
        recipes_found: recipes.slice(0, prevData.options.max_results),
        sources: input.sources || [],
        search_queries_used: input.search_queries || [prevData.query],
        raw_content: content.substring(0, 2000)
      },
      meta: {
        provider: prevData.provider,
        model: prevData.provider,
        search_engine: prevData.provider_type === 'gemini' ? 'google' : (prevData.provider_type === 'openai' ? 'bing' : 'brave'),
        search_performed: input.search_performed,
        sources_count: (input.sources || []).length
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to format output: ' + e.message,
        status: 'FORMAT_ERROR'
      },
      meta: { provider: prevData.provider }
    }
  }];
}
